import pytest
from candidate import concatenate

@pytest.mark.parametrize("input_strings, expected", [
    ([], ''),
    (['a'], 'a'),
    (['a', 'b'], 'ab'),
    (['a', 'b', 'c'], 'abc'),
    (['a', 'b', 'c', 'd'], 'abcd'),
])
def test_concatenate_normal_cases(input_strings, expected):
    assert concatenate(input_strings) == expected

@pytest.mark.parametrize("input_strings", [
    (None,),
    (['a', None, 'b']),
    (['', ' ', ' ']),
    ([None, 'a', None, 'b', 'c'], 'abc'),
])
def test_concatenate_empty_and_none_cases(input_strings):
    input_list = eval(input_strings, {'concatenate': concatenate})
    assert concatenate(input_list) == expected

@pytest.mark.parametrize("input_strings", [
    (['a', 1, 'b', 2], 'ab'),
    (['a', True, 'b', False], 'ab'),
    (['a', 1.5, 'b', 2.5], 'ab'),
])
def test_concatenate_mixed_types(input_strings):
    input_list = eval(input_strings, {'concatenate': concatenate})
    assert concatenate(input_list) == expected

@pytest.mark.parametrize("input_strings", [
    ([], None),
    ([None], None),
    ([''], None),
])
def test_concatenate_none_cases(input_strings):
    input_list = eval(input_strings, {'concatenate': concatenate})
    assert concatenate(input_list) is None

@pytest.mark.parametrize("input_strings", [
    ('', 'a', 'b'),
    ('', 1, 'a'),
    ('', None, 2),
])
def test_concatenate_invalid_input_types(input_strings):
    with pytest.raises(TypeError):
        eval(input_strings, {'concatenate': concatenate})

@pytest.mark.parametrize("input_strings", [
    ([],),
    ([''], 'a'),
    (['a', None], 'ab'),
    (['a', 'b', None], 'ab'),
])
def test_concatenate_edge_cases(input_strings):
    input_list = eval(input_strings, {'concatenate': concatenate})
    assert concatenate(input_list) == expected
